pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up a malicious actor that reverts on receive
        address malicious = address(0x1234);
        vm.deal(address(this), 10 ether);
        vm.deal(malicious, 0);

        // Step 1: Deposit from this test contract (the log contract) — must be > MinDeposit
        c.Deposit{value: 2 ether}();

        // Step 2: Transfer the balance from this contract to malicious via CashOut, but make malicious revert
        // We need to call CashOut from malicious's perspective, but first give it a balance by pranking as this contract
        // Actually, we can just have the test contract call CashOut for itself? No, CashOut sends to msg.sender
        // So let's first transfer ownership of the balance: we can't. Instead, let's do a deposit by malicious and then cashout with revert
        // Simpler: Use a contract that reverts on receive
        // Deploy a revert-on-receive contract
        address reverting = address(new RevertReceiver());
        vm.deal(reverting, 0);
        // Now prank as reverting to deposit (needs ether) — we can use vm.deal to give ether to reverting first
        vm.deal(reverting, 2 ether);
        vm.prank(reverting);
        c.Deposit{value: 2 ether}();

        // Now cashout from reverting, which will revert in receive and thus in the reference the balance stays
        vm.prank(reverting);
        // The call will revert if the receiver reverts, but we catch it
        bool ok;
        try c.CashOut(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, the balance was NOT deducted because the call reverted before the transfer log
        // In the buggy version, the balance WAS deducted before the call, so it's now reduced
        // Check balance of reverting after the attempt
        uint256 bal = c.balances(reverting);
        // Reference: should still be 2 ether (full deposit), buggy: should be 1 ether (deducted)
        assertEq(bal, 2 ether);
    }
}

contract RevertReceiver {
    receive() external payable {
        revert("I reject ether");
    }
}

